            (int) ((wordToHash[i] - (long) coefficient * val(dict[i].charAt(j)) % HASH + HASH) %
                   HASH);
        if (newHashToIndices.containsKey(newHash)) {
          for (final int index : newHashToIndices.get(newHash)) {
