    BASE = 26
    HASH = 1_000_000_007
    m = len(dict[0])

    def val(c: str) -> int:
      return ord(c) - ord('a')

    def getHash(s: str) -> int:
      """Returns the hash of `s`. Assume the length of `s` is m.

      e.g. getHash(s) = 26^(m - 1) * s[0] + 26^(m - 2) * s[1] + ... + s[m - 1].
      """
      hash = 0
      for c in s:
        hash = (hash * BASE + val(c))
      return hash

