 public:
  Node* buildTree(vector<string>& postfix) {
    stack<ExpNode*> stack;

    for (const string& val : postfix)
      if (val == "+" || val == "-" || val == "*" || val == "/") {
        ExpNode* right = stack.top();
        stack.pop();
        ExpNode* left = stack.top();
        stack.pop();
        stack.push(new ExpNode(val, left, right));
      } else {
        stack.push(new ExpNode(val, nullptr, nullptr));
      }

    return stack.top();
  }
};

